// src/pages/AdminDashboard.js
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { logout, fetchFranchiseData } from '../services/api'; // Adjust the path to your actual location

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [franchises, setFranchises] = useState([]);

  // Handle logout logic
  const handleLogout = async () => {
    try {
      const message = await logout();
      console.log(message); // Optional: Display the success message

      // Clear the token from localStorage
      localStorage.removeItem('token');

      // Navigate to the login page
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  // Fetch franchise data on component mount
  useEffect(() => {
    const getFranchises = async () => {
      try {
        const data = await fetchFranchiseData();
        setFranchises(data);
      } catch (error) {
        console.error('Error fetching franchise data:', error);
      }
    };

    getFranchises();
  }, []);

  return (
    <div style={styles.adminDashboard}>
      <h1 style={styles.heading}>Welcome to Admin Dashboard</h1>
      <div style={styles.dashboardButtons}>
        <button style={styles.adminButton} onClick={() => navigate('/create-user')}>Create User</button>
        <button style={styles.adminButton} onClick={() => navigate('/exam-data')}>Manage Exam Data</button>
        <button style={{ ...styles.adminButton, ...styles.logout }} onClick={handleLogout}>Logout</button>
      </div>

      {/* Franchise List Table */}
      <div style={{ width: '100%', overflowX: 'auto' }}>
        <table style={tableStyles.table}>
          <thead>
            <tr>
              <th style={tableStyles.th}>ID</th>
              <th style={tableStyles.th}>Name</th>
              <th style={tableStyles.th}>Location</th>
              <th style={tableStyles.th}>Status</th>
            </tr>
          </thead>
          <tbody>
            {franchises.map((franchise) => (
              <tr key={franchise.id} style={tableStyles.tr}>
                <td>{franchise.id}</td>
                <td>{franchise.name}</td>
                <td>{franchise.location}</td>
                <td>{franchise.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <style jsx>{`
        /* Table styling */
        .table-container {
          width: 100%;
          overflow-x: auto;
        }

        .table {
          width: 100%;
          border-collapse: collapse;
          margin-top: 20px;
        }

        .table th, .table td {
          padding: 12px;
          text-align: left;
          border-bottom: 1px solid #ddd;
        }

        .table th {
          background-color: #007bff;
          color: white;
        }

        .table tr:hover {
          background-color: #f1f1f1;
        }
      `}</style>
    </div>
  );
};

// CSS Styles in JS format
const styles = {
  adminDashboard: {
    display: 'flex',
    flexDirection: 'column',
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
  },
  heading: {
    fontSize: '2rem',
    marginBottom: '20px',
    textAlign: 'center',
  },
  dashboardButtons: {
    display: 'flex',
    gap: '15px',
    justifyContent: 'center',
    marginBottom: '20px',
  },
  adminButton: {
    padding: '10px 20px',
    fontSize: '16px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '5px',
    cursor: 'pointer',
    transition: 'background-color 0.3s ease',
  },
  logout: {
    backgroundColor: '#dc3545',
  },
};

const tableStyles = {
  table: {
    width: '100%',
    borderCollapse: 'collapse',
    marginTop: '20px',
  },
  th: {
    padding: '12px',
    textAlign: 'left',
    borderBottom: '1px solid #ddd',
    backgroundColor: '#007bff',
    color: 'white',
  },
  tr: {
    '&:hover': {
      backgroundColor: '#f1f1f1',
    },
  },
};

export default AdminDashboard;
